from collections import deque
G=[[0,5,0,0,0,0,0,5,0,0,5,0],[0,5,0,0,0,5,5,5,0,5,5,0],[5,5,5,0,0,5,0,5,5,5,0,0],[0,0,5,5,5,5,0,5,0,5,5,0],[0,0,0,5,0,0,0,5,0,0,5,0]]
h,w=len(G),len(G[0]); seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if G[r][c]==0 and (r,c) not in seen:
   q=[(r,c)];seen.add((r,c)); comp=[]
   while q:
    x,y=q.pop();comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and G[a][b]==0 and (a,b) not in seen: seen.add((a,b));q.append((a,b))
   comps.append(comp)
for i,c in enumerate(sorted(comps,key=len)):
 print(len(c), 'boundary',any(r in (0,h-1) or col in (0,w-1) for r,col in c), sorted(c))
